use super::*;
fn reserve<T>(owner:&mut NativeOwnedStorage<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=super::tests::with_effect(grant,1,|effect|owner.reserve_empty(effect));let turn=super::tests::complete(turn);let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());if turn.work==0{assert_eq!(actual,None)}else if turn.result.is_err(){assert_eq!(actual,Some(0))}else if NativeOwnedStorage::<T>::reserve_demand().capacity_bytes>0{assert_eq!(actual,Some(progress.retained_capacity_bytes))}turn}

fn release<T>(owner:&mut NativeOwnedStorage<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=super::tests::with_effect(grant,1,|effect|owner.release(effect));assert_eq!(actual,None);turn}

fn put<T>(owner:&mut NativeOwnedStorage<T>,input:&mut Option<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=super::tests::with_effect(grant,1,|effect|owner.put_from(input,effect));assert_eq!(actual,None);turn}
fn take<T>(owner:&mut NativeOwnedStorage<T>,output:&mut Option<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let(turn,actual)=super::tests::with_effect(grant,1,|effect|owner.take_into(output,effect));assert_eq!(actual,None);turn}
fn observed<R>(f:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(f)}
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u128,p:RetainedCloneProgress,work:u128,heap:(usize,usize)){assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close_text(value:String,bank:&mut RetainedCloneGrant,fuel:&mut u128){let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty(){return}let grant=RetainedCloneGrant{maximum_items:1,..*bank};let units=owner.next_computational_work(grant.maximum_copy_bytes).unwrap();let((result,actual),heap)=observed(||super::tests::with_effect(grant,units,|effect|owner.step(effect)));let turn=super::tests::complete(result);let work=turn.work;let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};if let Some(bytes)=actual{assert_eq!(bytes,p.retained_capacity_bytes)}debit(bank,fuel,p,work,heap);turn.result.unwrap();}panic!("typed storage output close exhausted original bank")}
#[test]fn actual_typed_storage_caller_slots_preserve_bodies_without_constructor_or_destructor_callbacks(){let f:serde_json::Value=serde_json::from_str(include_str!("../../📐️.json")).unwrap();let s=&f["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=u128::from(s["fuel"].as_u64().unwrap());let original=f["moveText"].as_str().unwrap().to_owned();let pointer=original.as_ptr();let mut input=Some(original);let mut owner=NativeOwnedStorage::<String>::empty();let g=RetainedCloneGrant{maximum_items:1,..bank};let((turn,attempts),heap)=observed(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||reserve(&mut owner,g)));assert_eq!(attempts,1);assert_eq!(turn.work,1);let error=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);assert_eq!(f["nullKind"],"AllocationFailed");debit(&mut bank,&mut fuel,error.retained_progress(),turn.work,heap);assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.reserved());let(turn,heap)=observed(||reserve(&mut owner,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work,heap);let address=owner.address();let(turn,heap)=observed(||put(&mut owner,&mut input,RetainedCloneGrant{maximum_items:0,..bank}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.initialized());let(turn,heap)=observed(||put(&mut owner,&mut input,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(work,1);assert_eq!(p.copied_bytes,NativeOwnedStorage::<String>::move_demand().copy_bytes);debit(&mut bank,&mut fuel,p,work,heap);assert!(input.is_none());assert_eq!(owner.get().unwrap().as_ptr(),pointer);assert_eq!(owner.address(),address);let(turn,heap)=observed(||release(&mut owner,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,u128::from(f["liveReleaseWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(owner.get().unwrap().as_ptr(),pointer);let mut output=Some(String::from("occupied"));let(turn,heap)=observed(||take(&mut owner,&mut output,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,u128::from(f["occupiedOutputWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(output.as_deref(),Some("occupied"));close_text(output.take().unwrap(),&mut bank,&mut fuel);let(turn,heap)=observed(||take(&mut owner,&mut output,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(work,1);assert_eq!(p.copied_bytes,NativeOwnedStorage::<String>::move_demand().copy_bytes);debit(&mut bank,&mut fuel,p,work,heap);assert!(!owner.initialized());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),f["moveText"]);let(turn,heap)=observed(||release(&mut owner,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work,heap);assert!(owner.terminal_is_empty());close_text(output.take().unwrap(),&mut bank,&mut fuel);assert_eq!(release(&mut owner,Default::default()).work,0);assert_eq!(observed(||drop(owner)).1,(0,0));}
